int lengthOfLIS(int* nums, int numsSize) {
    int* tails = malloc(sizeof(int) * numsSize); // tails[k] = 长度 k+1 的 LIS 最小结尾
    int size = 0;
    for (int i = 0; i < numsSize; ++i) {
        int lo = 0, hi = size;
        while (lo < hi) {                 // 二分找第一个 >= nums[i] 的位置
            int mid = (lo + hi) / 2;
            if (tails[mid] < nums[i]) lo = mid + 1; else hi = mid;
        }
        tails[lo] = nums[i];
        if (lo == size) ++size;
    }
    return size;
}

