func canPartition(nums []int) bool {
    s := 0
    for _, x := range nums {
        s += x
    }
    if s%2 != 0 {
        return false
    }

    n := len(nums)
    memo := make([][]int8, n)
    for i := range memo {
        memo[i] = make([]int8, s/2+1)
        for j := range memo[i] {
            memo[i][j] = -1 // -1 表示没有计算过
        }
    }

    var dfs func(int, int) bool
    dfs = func(i, j int) (res bool) {
        if i < 0 {
            return j == 0
        }
        p := &memo[i][j]
        if *p != -1 { // 之前计算过
            return *p == 1
        }

        if j < nums[i] {
            res = dfs(i-1, j) // 只能不选
        } else {
            res = dfs(i-1, j-nums[i]) || dfs(i-1, j) // 选或不选
        }
        // 记忆化
        if res {
            *p = 1
        } else {
            *p = 0
        }
        return
    }

    return dfs(n-1, s/2)
}

