class Solution {
public:
    ListNode* reverseKGroup(ListNode* head, int k) {
        ListNode dummy(0); dummy.next = head;
        ListNode* prevGroup = &dummy;
        while (true) {
            ListNode* probe = prevGroup;
            for (int i = 0; i < k && probe; i++) probe = probe->next;
            if (!probe) break;                       // 不足 k 个，结束
            ListNode* groupHead = prevGroup->next;
            ListNode* cur = groupHead->next;
            for (int i = 1; i < k; i++) {            // 组内头插反转
                ListNode* next = cur->next;
                cur->next = prevGroup->next;
                prevGroup->next = cur;
                cur = next;
            }
            groupHead->next = cur;                   // 反转后的尾接下一组头
            prevGroup = groupHead;
        }
        return dummy.next;
    }
};

