class Solution {
public:
    vector<int> inorderTraversal(TreeNode* root) {
        vector<int> out;
        vector<TreeNode*> stack;
        TreeNode* cur = root;
        while (cur || !stack.empty()) {
            while (cur) { stack.push_back(cur); cur = cur->left; }  // 一路向左
            cur = stack.back(); stack.pop_back();                   // 弹出访问
            out.push_back(cur->val);
            cur = cur->right;                                       // 转向右子树
        }
        return out;
    }
};

