class Solution:
    def pathSum(self, root: TreeNode, targetSum: int) -> int:
        prefix = {0: 1}
        count = 0
        def go(node, cur):
            nonlocal count
            if not node:
                return
            cur += node.val
            count += prefix.get(cur - targetSum, 0)   # 命中路径
            prefix[cur] = prefix.get(cur, 0) + 1
            go(node.left, cur)
            go(node.right, cur)
            prefix[cur] -= 1                          # 回溯撤销
        go(root, 0)
        return count

