class Solution:
    def generateParenthesis(self, n: int) -> List[str]:
        out, path = [], []
        def go(left, right):
            if len(path) == 2 * n:
                out.append("".join(path))
                return
            if left < n:
                path.append("("); go(left + 1, right); path.pop()
            if right < left:
                path.append(")"); go(left, right + 1); path.pop()
        go(0, 0)
