class MyQueue:
    def __init__(self):
        self.inS, self.outS = [], []
    def _shift(self):
        if not self.outS:
            while self.inS:
                self.outS.append(self.inS.pop())
    def push(self, x: int) -> None:
        self.inS.append(x)
    def pop(self) -> int:
        self._shift()
        return self.outS.pop()
    def peek(self) -> int:
        self._shift()
        return self.outS[-1]
    def empty(self) -> bool:
        return not self.inS and not self.outS

