        for ch in s:
            if ch.isdigit():
                num = num * 10 + int(ch)
            elif ch == '[':
                num_stack.append(num)
                str_stack.append(cur)
                cur, num = "", 0
            elif ch == ']':
                times = num_stack.pop()
                cur = str_stack.pop() + cur * times
            else:
                cur += ch
        return cur

